// CSD_RATIONALE_BEGIN
// SQL-generation CSD for the Spider dataset.
// State tracked: generated (full output including "SQL: <<" prefix), 
// insideConstrainedOut (whether we are inside a constrained span), 
// currentConstrainedOut (the active SQL fragment being built), steps (cost).
//
// Strategy:
// 1. Emit the literal prefix "SQL: " via unconstrained steps, watching for
//    the natural opening of the constrained span ("<<").
// 2. Once inside the constrained span, use AdaptiveConstrainedStep with the
//    caller-supplied validTokenGroups to generate the SQL query token by token.
//    The parser enforces SQL grammar validity at every step.
// 3. When the parser reports a complete parse, call CloseConstrainedSpan to
//    emit ">>" and exit constrained mode.
// 4. After the span closes, stop (the query is complete).
//
// The narrowThreshold is set to 20 so that group boosts activate when the
// parser's branching factor is small (e.g., after keywords like SELECT, FROM).
// This helps the model pick schema-grounded identifiers from validTokenGroups.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   Outside the span: the implication is vacuously true. When next == "<<" is
//   observed (either from UnconstrainedStep or OpenConstrainedSpan), we set
//   currentConstrainedOut := [], which satisfies IsValidPrefix([]) by the
//   method precondition parser.IsValidPrefix([]). So the implication holds.
//   Inside the span, CloseConstrainedSpan sets insideConstrainedOut := false,
//   making the implication vacuous. AdaptiveConstrainedStep returns EOS or a
//   parser-valid next token; AppendConstrainedToken extends currentConstrainedOut
//   by exactly that token, preserving IsValidPrefix by the parser contract.
//   CloseSpanIfComplete either closes (making implication vacuous) or is a no-op.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Every branch that increments steps appends at most one token to generated
//   (UnconstrainedStep appends at most one token; OpenConstrainedSpan appends
//   exactly one "<<" token; AppendConstrainedToken appends one token;
//   CloseConstrainedSpan appends one ">>" token). So generated grows by at most
//   1 per step increment, preserving the bound.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly: SQL: <<YOUR SQL QUERY>> using only the schema provided. No explanation. Valid SQL only.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 20;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    // Query is complete; stop generating
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Analysis of failure mode: The previous attempt had 64.3% syntax rate and 36.3% accuracy.
// Key issues observed:
// 1. "No complete visible spans" - 300/300 examples had no complete visible spans
//    but 193/300 had "unmatched visible close" - meaning ">>" appeared without matching "<<"
//    This means the model was generating ">>" as part of the SQL content, which is wrong.
// 2. The model was generating SQL with table aliases (e.g., "s.name") but the parser
//    likely expected fully qualified names.
// 3. Repetition loops occurred - the model kept repeating column names.
// 4. The model stopped too early (most examples had low token counts, avg 18.03).
//
// Root cause: The unconstrained preamble phase was too long - the model was generating
// SQL content BEFORE entering the constrained span, or the "<<" was never observed in
// the free-generation phase, so the SQL was generated outside the parser's control.
//
// The diagnostic shows:
// - "Examples with visible `<<`: 0/300" - the model NEVER generated "<<" in unconstrained mode!
// - But "Examples with unmatched visible close: 193/300" - the parser was still being used
// - "Constrained helper call fraction: 1.00" - constrained helpers were called
//
// This means the model was entering the constrained span via some mechanism but not 
// emitting visible "<<". The strategy must FORCE the "<<" opening delimiter explicitly
// using OpenConstrainedSpan rather than waiting for the model to emit it naturally.
//
// Fix: Use OpenConstrainedSpan immediately to force entry into constrained mode,
// then generate the SQL query under full parser control with SafeRepetitionPenaltyStep
// to avoid repetition loops. The task contract is "SQL: <<QUERY>>".
//
// The guidance should instruct the model to emit "SQL: " prefix before the span,
// and we force the span open with OpenConstrainedSpan after letting the model emit
// the "SQL: " prefix via a very limited unconstrained preamble.
//
// Strategy:
// 1. Emit "SQL: " via a short unconstrained preamble (budget: ~10 steps)
// 2. Force "<<" via OpenConstrainedSpan
// 3. Generate SQL under full parser control with repetition penalty
// 4. Close when complete
//
// To avoid repetition: use SafeRepetitionPenaltyStep inside the constrained span.
// To ensure correct SQL: use AdaptiveConstrainedStep with group boosts.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   Phase 1 (unconstrained preamble): insideConstrainedOut is false throughout,
//   so the implication is vacuously true. If by chance the model emits "<<",
//   we set currentConstrainedOut := [] which satisfies IsValidPrefix([]).
//   Phase 2 (forced span open): OpenConstrainedSpan sets insideConstrainedOut := true
//   and currentConstrainedOut := [], which satisfies IsValidPrefix([]) by precondition.
//   Phase 3 (constrained generation): SafeRepetitionPenaltyStep returns EOS or a
//   parser-valid next token. AppendConstrainedToken extends currentConstrainedOut
//   by exactly that token, preserving IsValidPrefix by the parser contract.
//   CloseConstrainedSpan sets insideConstrainedOut := false, making the implication vacuous.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Phase 1: Each UnconstrainedStep consumes 1 step and appends at most 1 token.
//   Phase 2: OpenConstrainedSpan consumes 1 step and appends exactly 1 "<<" token.
//   Phase 3: Each SafeRepetitionPenaltyStep consumes 1 step; AppendConstrainedToken
//   appends exactly 1 token (not counted as a step). CloseConstrainedSpan consumes 1 step
//   and appends at most 1 ">>" token. So |generated| grows by at most 1 per step.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Generate a single SQL query. Output format: SQL: <<query>>. Use only tables and columns from the provided schema. Write concise, correct SQL with proper JOINs and aggregations.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Short unconstrained preamble to emit "SQL: " prefix
// Limit to at most 15 steps for the preamble, then force the span open
var preambleBudget: nat := 15;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: If not yet inside constrained span, force entry with OpenConstrainedSpan
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under full parser control with repetition penalty
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    // Use repetition penalty to avoid loops, combined with group boosting for schema tokens
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Try to close the span cleanly if possible
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := closedGenerated;
        insideConstrainedOut := closedInside;
        currentConstrainedOut := closedCurrent;
        steps := steps + 1;
      }
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

// If span is still open and we have budget, try CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Analysis of failure modes across attempts:
// 1. Attempt 1 (best: 36.3% accuracy, 64.3% syntax): Strategy waited for the model to
//    naturally emit "<<", then used AdaptiveConstrainedStep inside the span. Problem:
//    the model often never emitted "<<" in unconstrained mode (0/300 visible "<<").
//    But somehow the constrained code still ran (via span state tracking).
//    The key insight: the diagnostic says "0 examples with visible <<"  but
//    "300 examples with constrained activity". This means the span was being entered
//    via some other mechanism. BUT looking at the failing outputs, the SQL was generated
//    WITHOUT the "<<" prefix visible, meaning the evaluator couldn't find the answer.
//
// 2. Attempt 2 (12.0% accuracy, 56.7% syntax): Used OpenConstrainedSpan to force "<<"
//    but this STILL showed 0 visible "<<" examples. This means OpenConstrainedSpan
//    doesn't produce visible "<<" in the output - or the evaluator strips them.
//    Wait - re-reading: "Examples with visible <<: 0/300" - this is about the GENERATED
//    output, not the strategy. The model generates output that starts with "SQL: " prefix
//    but the "<<" is being consumed/hidden somewhere.
//
// Key insight from diagnostics:
// - "answer_source: text_fallback" for 0 examples, "hidden_or_task_extractor" for 0
// - "final_answer_span: 0/300, valid_nonfinal_spans_only: 300/300"
// - This means valid spans ARE being generated, but they are non-final (not the last span)
// - So the model IS generating constrained content, but then the span closes early and
//   more unconstrained content follows, or the span content is wrong.
//
// The critical issue: "No complete visible spans: 300/300" but "valid span/chunk: 300/300"
// This means the constrained content is being generated as a "hidden" span (not visible).
//
// Looking at the outputs: "SELECT s.name !" - the "<<" and ">>" are NOT present in the
// visible output. The model outputs raw SQL without delimiters.
//
// The task requires "SQL: <<YOUR QUERY>>". The evaluator extracts the content between << and >>.
// If the model outputs "SQL: SELECT..." without delimiters, the evaluator uses text_fallback
// or another extraction method.
//
// Strategy fix: We need to ensure "<<" and ">>" are VISIBLY present in the output.
// The problem with previous attempts is that "OpenConstrainedSpan" forces "<<" into
// generated but the model then generates SQL that may not include ">>" at the end.
// OR the unconstrained preamble never included "<<" because the model was directly
// generating SQL.
//
// NEW APPROACH:
// 1. Force "SQL: " preamble via very short unconstrained (at most 5 tokens)
// 2. Explicitly force "<<" via OpenConstrainedSpan
// 3. Generate SQL under FULL hard parser control (ConstrainedStep, not Adaptive)
//    to ensure grammar validity 
// 4. Close span with CloseSpanWithinBudget for reliable ">>"
// 5. Use SafeRepetitionPenaltyStep to avoid repetition loops (the "too slow" example)
//
// The key change: use ConstrainedStep (hard parser control) rather than AdaptiveConstrainedStep
// and add repetition penalty to avoid the runaway expansion seen in the "too slow" example.
// Also limit preamble to 5 steps max, then FORCE the span open regardless.
//
// Additionally, looking at the correct answers - they use lowercase SQL with spaces around
// parentheses. The parser should handle this but we need the right token vocabulary.
// The validTokenGroups from the caller should contain schema-grounded tokens.
//
// CRITICAL: The "Span usefulness: valid_nonfinal_spans_only: 300/300" means the spans ARE
// being closed but they are not the FINAL span in the output. After closing the span,
// the model continues generating unconstrained content that follows the ">>" token.
// We need to STOP immediately after closing the span.
//
// So the actual bug in attempt 1 was: after CloseConstrainedSpan, we did "break" - 
// that should have worked. But wait - "valid_nonfinal_spans_only: 300/300" means
// the span IS there but is not the final token sequence. Perhaps the evaluator
// looks for the LAST span in the output, and if there's content after ">>" it
// considers that a non-final span.
//
// OR: The "valid span" is the hidden constrained chunk, not a visible "<<...>>" span.
// The diagnostic "zero_visible_spans=yes" (in clusters) confirms: the spans are HIDDEN.
//
// The real issue: OpenConstrainedSpan appends "<<" to generated, but looking at the
// outputs in failures, no "<<" appears. This could mean:
// a) The strategy was entering the span WITHOUT going through OpenConstrainedSpan
//    (i.e., the preamble never reached the OpenConstrainedSpan call because EOS was hit first)
// b) OR the "<<" token is being filtered from display
//
// In attempt 2: preamble was 15 steps, then OpenConstrainedSpan. But avg generated tokens
// was 13.29. So the model WAS hitting EOS before the 15-step preamble ended, meaning
// OpenConstrainedSpan was never reached!
//
// FIX: Reduce preamble to 3 steps MAX, then ALWAYS call OpenConstrainedSpan before
// generating any SQL content. This ensures "<<" is always in the output.
// Then use aggressive repetition penalty + group boosting to generate correct SQL.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   Phase 1 (preamble): insideConstrainedOut remains false (or becomes true if "<<"
//   is naturally emitted), so the implication is vacuous or holds trivially ([] is valid).
//   Phase 2 (forced span): OpenConstrainedSpan sets currentConstrainedOut := [] which
//   satisfies IsValidPrefix([]) by the method precondition parser.IsValidPrefix([]).
//   Phase 3 (constrained generation):
//     - SafeRepetitionPenaltyStep returns EOS or a parser-valid next token.
//     - AppendConstrainedToken extends currentConstrainedOut by that token, preserving
//       IsValidPrefix by the parser contract.
//     - CloseConstrainedSpan / CloseSpanWithinBudget sets insideConstrainedOut := false,
//       making the implication vacuously true.
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token.
//   Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   Phase 3: Each SafeRepetitionPenaltyStep increments steps by 1; AppendConstrainedToken
//   appends 1 token without incrementing steps; CloseConstrainedSpan increments steps by 1
//   and appends at most 1 ">>" token; CloseSpanWithinBudget uses at most closeBudget steps
//   and appends at most closeBudget tokens. So |generated| <= |generatedPrefix| + steps always.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly: SQL: <<YOUR SQL QUERY HERE>> using only the schema provided. The query must be between << and >>. No explanation, no markdown.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Very short unconstrained preamble (at most 3 steps) to emit "SQL: " prefix
// Keep this tiny so we don't hit EOS before entering the constrained span
var preambleBudget: nat := 3;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    // Don't break - we need to still open the span if we have budget
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under constrained control with repetition penalty
// Use SafeRepetitionPenaltyStep to avoid runaway repetition loops
// Also use group boosting for schema-grounded vocabulary
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    // Use adaptive constrained step with group boosts for schema tokens
    // and narrow threshold to activate boosts when parser branching is limited
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 20, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Try to close cleanly if possible
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := closedGenerated;
        insideConstrainedOut := closedInside;
        currentConstrainedOut := closedCurrent;
        steps := steps + 1;
      }
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

// CSD_RATIONALE_BEGIN
// The previous attempt failed because RepetitionPenaltyStep requires
// `forall t :: t in generated ==> t in lm.Tokens`, which cannot be proven
// for the accumulated `generated` sequence. The fix is to replace
// RepetitionPenaltyStep with AdaptiveConstrainedStep (or GroupBoostedConstrainedStep),
// which has no such precondition on generated tokens.
//
// Strategy:
// 1. Short unconstrained preamble (up to 5 steps) to emit "SQL: " prefix
// 2. Force "<<" open if not already in constrained span
// 3. Generate SQL under constrained control using AdaptiveConstrainedStep
//    with group boosts from validTokenGroups
// 4. Only close when minSpanTokens threshold is met to prevent premature closure
// 5. CloseSpanWithinBudget for any remaining open span
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   Phase 1 (preamble): insideConstrainedOut stays false unless "<<" is naturally
//   emitted, in which case currentConstrainedOut := [] is valid by precondition.
//   Phase 2 (forced open): OpenConstrainedSpan sets currentConstrainedOut := [],
//   and parser.IsValidPrefix([]) holds by precondition.
//   Phase 3 (constrained loop):
//     - If spanTokens < minSpanTokens or not complete: AdaptiveConstrainedStep returns
//       EOS or a parser-valid next token; AppendConstrainedToken extends
//       currentConstrainedOut while preserving parser.IsValidPrefix.
//     - If parser.IsCompletePrefix && spanTokens >= minSpanTokens: CloseConstrainedSpan
//       sets insideConstrainedOut := false, making the implication vacuous.
//   Phase 4 (CloseSpanWithinBudget): postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// progress invariant (|generated| <= |generatedPrefix| + steps):
//   Phase 1: each UnconstrainedStep increments steps by 1 and appends at most 1 token.
//   Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   Phase 3: AdaptiveConstrainedStep increments steps by 1; AppendConstrainedToken
//   appends exactly 1 token without incrementing steps; CloseConstrainedSpan increments
//   steps by 1 and appends at most 1 ">>" token.
//   Phase 4: CloseSpanWithinBudget uses at most closeBudget steps; setting steps := maxSteps
//   bounds the invariant.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output exactly: SQL: <<YOUR SQL QUERY HERE>> using only the schema provided. The query must be between << and >>. No explanation, no markdown.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Short unconstrained preamble to let model emit "SQL: " prefix
var preambleBudget: nat := 5;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under constrained control
// Enforce minimum span token count to prevent premature closure
var minSpanTokens: nat := 10;
var spanTokens: nat := 0;

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
