// 1. Use TemperatureConstrainedStep with low temperature to make model more decisive
// 2. Add penalization of repeated tokens using SafeBoostTokenLogits with negative amounts
//    applied to tokens that appear frequently in currentConstrainedOut
//
// For the repetition issue: Before each constrained step, use MaskTokensInPrefix or
// apply PenalizeTokenLogits to tokens that appeared many times. But PenalizeTokenLogits
// requires tokens in lm.Tokens.
//
// Actually: RepetitionPenaltyStep(lm, parser, prompt, currentConstrained, generated, penaltyAmount, eosToken)
// This AUTOMATICALLY applies repetition penalty based on tokens in 'generated'.
// The precondition says... let me check: it's a "non-safe variant imposes the same
// membership proofs as the underlying penalize helper". So it requires tokens in lm.Tokens.
// Without proof, we can't call it safely.
//
// BUT: We CAN use PenalizedConstrainedStep with an empty penalize list, which is safe.
// Or we can track which tokens to penalize and only include safe ones.
//
// Actually: Let's try a completely different angle.
// The problem is 132 semantic mismatches with SHORT queries (avg 11.79 tokens total including preamble).
// Most SQL queries are 10-50 tokens. If avg total is 11.79, and preamble is ~5 tokens,
// then avg SQL is ~6-7 tokens. That's extremely short - just "SELECT col FROM table" with no WHERE/JOIN.
//
// The model is generating correct-syntax but overly-simplified SQL. The correct answers
// often need WHERE clauses, GROUP BY, JOIN, subqueries, etc.
//
// Fix: Increase the stepTokenBudget utilization. The model is closing the span too early
// (at the first IsCompletePrefix point). If we SKIP the early close and force the model
// to generate more tokens, we might get better SQL.
//
// But if we skip early close, the model might generate too-long SQL or repetitive SQL.
//
// Better fix: Use ConfidenceGatedStep - if the model is very confident about closing
// (EOS or completion), let it close; otherwise force more tokens.
//
// Or: Delay the IsCompletePrefix check until we've generated at least some minimum
// number of tokens (e.g., don't close until |currentConstrainedOut| >= 10).
//
// This would force the model to generate longer, more complete SQL queries!
//
// Let's try: minimum span length = 15 tokens before allowing close.
// SQL queries need at minimum "SELECT x FROM y" which is at least 4 tokens.
// More complex queries need 15-50 tokens.
//
// With minimum length 15:
// - Short queries like "SELECT city !" would be forced to continue
// - The model would be pushed to add WHERE, GROUP BY, etc.
// - This might convert "SELECT city" -> "SELECT city FROM employee WHERE age < 30 GROUP BY city HAVING count(*) > 1"
//
// RISK: Some correct answers ARE short (like "SELECT COUNT(*) FROM table"). These would be
// forced to continue and might generate wrong extra tokens.
//
// The minimum should be calibrated carefully. Let's try 8 tokens minimum.
//
// Implementation: Replace `parser.IsCompletePrefix(currentConstrainedOut)` check with
// `parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSqlLength`
//
// This is a simple, verifiable change that could significantly improve semantics.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble, UnconstrainedStep loop with !insideConstrainedOut guard):
//   The loop condition includes !insideConstrainedOut. If "<<" is emitted naturally,
//   we set currentConstrainedOut := [] which satisfies parser.IsValidPrefix([]) by precondition.
//   Outside "<<", insideConstrainedOut stays false so the implication is vacuous.
//
// Phase 2 (OpenConstrainedSpan):
//   Only reached when !insideConstrainedOut. Sets currentConstrainedOut := [] and
//   insideConstrainedOut := true. parser.IsValidPrefix([]) holds by precondition.
//
// Phase 3 (constrained generation):
//   IsCompletePrefix + minSqlLength check branch: CloseConstrainedSpan sets
//   insideConstrainedOut := false, making the implication vacuously true.
//   GroupBoostedConstrainedStep returns EOS or a parser-valid next token (hard mask enforced).
//   In the EOS case we break. In the non-EOS case, AppendConstrainedToken extends
//   currentConstrainedOut to currentConstrainedOut + [next], which remains parser.IsValidPrefix
//   by the IsTokenValidNext postcondition of GroupBoostedConstrainedStep.
//
// Phase 4 (CloseSpanWithinBudget):
//   Postcondition guarantees: insideOut ==> parser.IsValidPrefix(currentOut). Preserved.
//
// progress: |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 non-EOS token.
//   If EOS, break without appending. So |generated| grows by at most 1 per iteration
//   while steps grows by exactly 1. Invariant maintained.
//
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token and steps += 1.
//   Both sides grow by exactly 1. Invariant preserved.
//
// Phase 3:
//   IsCompletePrefix + minSqlLength branch: CloseConstrainedSpan increments steps by 1,
//   appends at most 1 ">>" token. Both sides grow by at most 1.
//   GroupBoostedConstrainedStep: steps += 1 always. AppendConstrainedToken appends
//   1 token (non-EOS case). Net: steps += 1, |generated| += 1. Invariant preserved.
//   EOS path: steps += 1 for the constrained step, plus maybe steps += 1 for CloseConstrainedSpan.
//   generated grows by at most 1 (">>" from close). |generated| <= |generatedPrefix| + steps.
//
// Phase 4: closeBudget = maxSteps - steps. CloseSpanWithinBudget adds at most closeBudget
//   to generated length, and we set steps := maxSteps.
//   So |generated| <= |generatedPrefix| + maxSteps. Invariant preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Generate a SQL SELECT query using ONLY the exact table and column names from the schema. Output format: SQL: <<query>>. The query MUST include FROM clause and appropriate WHERE/JOIN/GROUP BY as needed to answer the question correctly.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Minimum SQL token length before allowing span close (forces more complete queries)
var minSqlLength: nat := 8;

// Phase 1: Short unconstrained preamble (at most 5 steps) to emit "SQL: " prefix
var preambleBudget: nat := 5;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if next == "<<" {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with group boosting
// Only close when parser is complete AND we have enough tokens for a meaningful query
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Only close if we have a complete parse AND minimum length satisfied
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSqlLength {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Try to close cleanly if complete (even if under minSqlLength, to respect EOS)
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := closedGenerated;
        insideConstrainedOut := closedInside;
        currentConstrainedOut := closedCurrent;
        steps := steps + 1;
      }
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;
